            },
            {
              "between": [
                "src/frontend",
                "src/dashboard"
              ],
              "allow": [
                "src/shared"
              ],
              "reason": "the public site and the operator console ship to different hosts and answer to different people; a component shared between them would couple a reader-facing promise to an internal tool"
            }
          ]
        }
      }
    },
    {
      "id": "claudinite-lifecycle",
      "version": "60906.3"
