1	// The growth-dedup CODE-WORK: detect what the mounted canon changed in the window,
2	// and write the brief the agentic phase starts from.
3	//
4	// A run woken by canon movement used to be told only WHICH declared packs moved.
5	// A pack is a corpus, so that sent the run re-reading all of it for coverage that
6	// mostly predates the window, while the thing that can NEWLY cover a local item —
7	// what the canon ADDED in those days — was nowhere in the dispatch. Detecting it
8	// is deterministic code over the commit records, which is code-work's half of the
9	// task, not the agent's.
10	//
11	// Two kinds of addition, and the second is why a prose-only read is not enough: a
12	// canon **check** enforces its rule on every session and CI pass, which covers a
13	// local item more strongly than a stated line does, and it is invisible in the
14	// prose corpus. The brief carries both.
15	//
16	// The channel is the REPOSITORY, per the code-work contract (task-code-work DESIGN
17	// §3): no code→agent data channel exists, so the brief is posted as a COMMENT on
18	// the run's own work item, whose number code-work is handed as CLAUDINITE_ITEM.
19	// The item is where the agentic phase is already reading, the brief describes THIS
20	// window and nothing else, and both die together when the item converges — which
21	// is the whole life the brief has. A standing issue would outlive it by a week and
22	// then hold a stale window.
23	
24	import { writeFileSync } from 'node:fs';
25	import { pathToFileURL } from 'node:url';
26	import { makeGh } from '../../../claudinite-tasks/shared-code/github.mjs';
27	import { loadConfig } from '../../../../engine/checks/helpers/repo-context.mjs';
28	
29	const log = (s) => console.log(`growth-dedup code_work: ${s}`);
30	
31	// The window this task's own cadence covers — `frequency: 'weekly'` in task.json.
32	export const WINDOW_DAYS = 7;
33	
34	// A canon pack's file, in the two-root form: the mount prefix is optional because
35	// the canon home runs this same code from its repo root, where the shared packs
36	// ARE `packs/`. A local pack (`.claudinite/local/packs/…`) matches neither root
37	// — deliberately: it is what this task prunes, never the yardstick it prunes
38	// against.
39	const CANON_PACK_FILE = /^(?:\.claudinite\/shared\/)?packs\/([^/]+)\/.+/;
40	
41	// A rule id as a pack's declared-checks.json spells it — `id`, the key that file
42	// actually uses (`rule` is the settings vocabulary for overriding one, a
43	// different file). A drift guard in the pack's tests parses the real
44	// declared-checks.json through this, because keyed on the wrong word it silently
45	// returns nothing on every real patch while fixtures stay green.
46	const CHECK_ID = /"id"\s*:\s*"([^"]+)"/;
47	
48	// How many added lines one file contributes to the brief. A heavy canon week can
49	// move a whole RULES.md rewrite; the remainder is COUNTED in its place, so a
50	// truncated brief never reads as the complete set of what the canon added.
51	export const MAX_ADDED_LINES_PER_FILE = 40;
52	
53	// The whole brief's budget, against GitHub's 65536-byte cap on an issue comment. Measured
54	// need: the canon home's own busiest week rendered 350KB unbudgeted, so this is
55	// a live constraint, not a theoretical one. What the budget rations is the added
56	// LINES; every changed file is named regardless, since that list is cheap and is
57	// the run's map of where to look for what the budget left out.
58	export const MAX_BRIEF_BYTES = 60000;
59	
60	/** The declared canon pack a repo path belongs to, or null. */
61	export function canonPackOf(path) {
62	  return CANON_PACK_FILE.exec(path)?.[1] ?? null;
63	}
64	
65	/** The lines a unified-diff patch ADDED, marker stripped. */
66	export function addedLines(patch) {
67	  if (typeof patch !== 'string') return [];
68	  return patch.split('\n')
69	    .filter((l) => l.startsWith('+') && !l.startsWith('+++'))
70	    .map((l) => l.slice(1));
71	}
72	
73	/** The check rule ids a declared-checks.json patch ADDED. */
74	export function addedCheckIds(patch) {
75	  return addedLines(patch).map((l) => CHECK_ID.exec(l)?.[1]).filter(Boolean);
76	}
77	
78	/**
79	 * What the declared canon packs gained in the window. Pure over the commit
80	 * records (`{ sha, message, files: [{ filename, patch }] }`) the API returns.
81	 *
82	 * ADDITIONS ONLY. A line the canon REMOVED can never justify a prune — coverage
83	 * the canon just dropped is coverage that is gone, and a local item carrying it
84	 * has become load-bearing rather than redundant — so a `-` line is not offered
85	 * here as something to prune against.
86	 */
87	export function summarizeCanonWindow(commits, declaredPacks) {
88	  const declared = new Set(declaredPacks ?? []);
89	  const packs = {};
90	  let addedLineCount = 0;
91	  let fileCount = 0;
92	
93	  for (const c of commits ?? []) {
94	    for (const f of c.files ?? []) {
95	      const pack = canonPackOf(f.filename ?? '');
96	      if (!pack || !declared.has(pack)) continue;
97	
98	      const entry = (packs[pack] ??= { files: {}, newCheckIds: [] });
99	      const file = entry.files[f.filename] ?? (fileCount += 1, entry.files[f.filename] = { added: [], patchUnavailable: false });
100	
101	      // GitHub omits `patch` on a very large diff. Say so rather than record the
102	      // file as having added nothing — "the canon did not move here" is the one
103	      // claim this brief must never make falsely.
104	      if (typeof f.patch !== 'string') { file.patchUnavailable = true; continue; }
105	
106	      const added = addedLines(f.patch);
107	      file.added.push(...added);
108	      addedLineCount += added.length;
109	      if (f.filename.endsWith('declared-checks.json')) {
110	        for (const id of addedCheckIds(f.patch)) if (!entry.newCheckIds.includes(id)) entry.newCheckIds.push(id);
111	      }
112	    }
113	  }
114	  return { packs, addedLineCount, fileCount };
115	}
116	
117	/**
118	 * The brief: the window's canon additions, as the run's starting point.
119	 *
120	 * Two tiers, because they have different worth per byte. The MAP — each pack's
121	 * new check ids and the paths of every file that moved — is always complete: it
122	 * is what tells the run where to look, and it is cheap. The ADDITIONS are what
123	 * the budget rations, in map order, and what the budget leaves out is counted at
124	 * the end. A brief that quietly showed a prefix of the window would read as the
125	 * whole of it.
126	 */
127	export function renderBrief(summary, { sinceIso }) {
128	  const out = [];
129	  let spent = 0;
130	  const push = (...lines) => { out.push(...lines); spent += lines.join('\n').length + 1; };
131	
132	  push(
133	    `# Canon window diff — since ${sinceIso}`,
134	    '',
135	    'Written by the `growth-dedup` code_work at the top of this run:',
136	    'this describes the CURRENT window only. It is where the run starts, not what it may cite —',
137	    'a prune may still quote an older line in one of these packs.',
138	    '',
139	  );
140	  const entries = Object.entries(summary.packs);
141	  if (!entries.length) {
142	    push('No declared canon pack moved in this window. Compare the local packs against the mounted canon as a whole.');
143	    return out.join('\n') + '\n';
144	  }
145	
146	  // Tier 1 — the map.
147	  for (const [pack, { files, newCheckIds }] of entries) {
148	    push(`## ${pack}`, '');
149	    if (newCheckIds.length) {
150	      push(`**New checks** (a check covers a local item more strongly than prose): ${newCheckIds.map((id) => `\`${id}\``).join(', ')}`, '');
151	    }
152	    push('Files that moved:', '');
153	    for (const [path, file] of Object.entries(files)) {
154	      const note = file.patchUnavailable ? ' — no patch (diff too large); read the file whole'
155	        : file.added.length ? '' : ' — removals only, nothing added to prune against';
156	      push(`- \`${path}\`${note}`);
157	    }
158	    push('');
159	  }
160	
161	  // Tier 2 — the additions, in map order, until the budget is spent.
162	  push('## What the canon added', '');
163	  let omitted = 0;
164	  for (const [, { files }] of entries) {
165	    for (const [path, file] of Object.entries(files)) {
166	      if (!file.added.length) continue;
167	      const shown = file.added.slice(0, MAX_ADDED_LINES_PER_FILE);
168	      const rest = file.added.length - shown.length;
169	      const block = [
170	        `### \`${path}\``, '', '```', ...shown, '```',
171	        ...(rest > 0 ? ['', `_…and ${rest} more added line${rest === 1 ? '' : 's'} in this file — read its diff for the rest._`] : []),
172	        '',
173	      ];
174	      if (spent + block.join('\n').length > MAX_BRIEF_BYTES) { omitted += 1; continue; }
175	      push(...block);
176	    }
177	  }
178	  if (omitted) {
179	    push(
180	      '---', '',
181	      `**This brief hit its size budget**: additions for ${omitted} further file${omitted === 1 ? '' : 's'} are not shown.`,
182	      'Every file that moved is named in the map above — read the diff of the omitted ones directly.', '',
183	    );
184	  }
185	  // The map tier is unbudgeted by design, so a window that moved thousands of
186	  // files could still overrun on the map alone. Cut it rather than let the issue
187	  // write 422 and fail the run on its first step — and say that it was cut.
188	  const body = out.join('\n') + '\n';
189	  if (body.length <= MAX_BRIEF_BYTES) return body;
190	  return `${body.slice(0, MAX_BRIEF_BYTES)}\n\n_**Truncated at ${MAX_BRIEF_BYTES} bytes** — this window moved more of the canon than one issue body holds._\n`;
191	}
192	
193	/** The one line the work item shows for why the agent is here. */
194	export function handoffDetail(summary) {
195	  const packs = Object.keys(summary.packs);
196	  if (!packs.length) return 'no canon pack moved in the window — comparing against the mounted canon as a whole';
197	  const checks = packs.reduce((n, p) => n + summary.packs[p].newCheckIds.length, 0);
198	  return `${summary.addedLineCount} added line(s) across ${summary.fileCount} file(s) in ${packs.join(', ')}`
199	    + `, ${checks} new check${checks === 1 ? '' : 's'}`;
200	}
201	
202	// --- the I/O shell -----------------------------------------------------------
203	
204	// Every window commit with its files resolved — the per-commit read is what
205	// carries `patch`, which the listing does not.
206	async function windowCommits(gh, repo, branch, sinceIso) {
207	  const listed = await gh(`/repos/${repo}/commits?sha=${encodeURIComponent(branch)}&since=${sinceIso}&per_page=100`);
208	  if (listed.status !== 200) throw new Error(`commit listing unreadable: GET commits returned ${listed.status}`);
209	  const out = [];
210	  for (const c of listed.json ?? []) {
211	    const { status, json } = await gh(`/repos/${repo}/commits/${c.sha}`);
212	    if (status !== 200) continue; // one unreadable commit is a thinner brief, never a failed run
213	    out.push({ sha: c.sha, message: json?.commit?.message ?? '', files: json?.files ?? [] });
214	  }
215	  return out;
216	}
217	
218	async function main() {
219	  const repo = process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
220	  if (!repo || !repo.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
221	  if (!process.env.GITHUB_TOKEN) throw new Error('GITHUB_TOKEN is not set — the scheduler always provides it');
222	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
223	  const branch = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
224	  const gh = makeGh();
225	
226	  const sinceIso = new Date(Date.now() - WINDOW_DAYS * 86400000).toISOString();
227	  // The repo's OWN declaration decides which packs are the yardstick: a canon
228	  // pack it does not declare contributes no prose, no checks and no coverage.
229	  // `loadConfig` normalizes a local pack's `local/<id>` token to the bare id, so
230	  // this list mixes both kinds — and needs no filter, since the mount roots
231	  // `canonPackOf` matches exclude the local tree outright.
232	  const declared = loadConfig(root).packs ?? [];
233	  const summary = summarizeCanonWindow(await windowCommits(gh, repo, branch, sinceIso), declared);
234	
235	  // The brief, onto the run's OWN work item. `CLAUDINITE_ITEM` is the number the
236	  // queue hands every code-work run; without it there is nowhere to put the brief
237	  // and the agentic phase would start from nothing, so this is a hard failure.
238	  const item = process.env.CLAUDINITE_ITEM;
239	  if (!item) throw new Error('CLAUDINITE_ITEM is not set — nowhere to post the window brief');
240	  const posted = await gh(`/repos/${repo}/issues/${item}/comments`, {
241	    method: 'POST',
242	    body: { body: renderBrief(summary, { sinceIso }) },
243	  });
244	  if (posted.status >= 300) throw new Error(`could not post the window brief to #${item}: POST returned ${posted.status}`);
245	  const detail = handoffDetail(summary);
246	  log(`window brief posted to work item #${item} — ${detail}`);
247	
248	  // ALWAYS hand off. The precondition already decided this run happens, and an
249	  // empty canon window still leaves the repo's fresh local items to re-check, so
250	  // there is no condition here to re-litigate — only work code-work cannot do:
251	  // judging whether an added canon line genuinely covers a local item.
252	  const requestPath = process.env.CLAUDINITE_REQUEST_AGENT;
253	  if (!requestPath) throw new Error('CLAUDINITE_REQUEST_AGENT is not set — cannot hand off to the agentic phase');
254	  // No `delivered`: the brief is a comment on the item the agentic phase is already
255	  // reading, so there is no artifact identity this run has to hand over.
256	  writeFileSync(requestPath, JSON.stringify({
257	    reason: { code: 'canon-window-diff', detail },
258	  }));
259	}
260	
261	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
262	  main().catch((e) => { console.error(`growth-dedup code_work failed: ${e.message}`); process.exit(1); });
263	}
264

